def bracket(q):
    """Smallest positive integer k with |q| > 1/k, EXACTLY.  None if q == 0."""
    q = sp.Abs(sp.cancel(q))
    if q == 0:
        return None
    n, d = sp.fraction(q)
    k = sp.Integer(d) // sp.Integer(n) + 1
    return int(k) if q > R(1, k) else int(k) + 1


def floor_scaled(q, den=10 ** 7):
    """floor(|q| * den) as an exact Integer.  The report's own quoting form:
    the exact rational bracket is [floor/den, (floor+1)/den)."""
    return sp.floor(sp.Abs(sp.cancel(q)) * den)


